    descriptionAdvanced: {
      de: "Das Pantanal ist das größte tropische Feuchtgebiet der Welt und erstreckt sich über eine Fläche von etwa 140.000 bis 195.000 Quadratkilometern, hauptsächlich in den brasilianischen Bundesstaaten Mato Grosso und Mato Grosso do Sul. Es handelt sich um eine riesige Sedimentebene, die während der Regenzeit von November bis März zu etwa 80 % überflutet wird. Diese saisonalen Überschwemmungen schaffen ein dynamisches Mosaik aus Seen, Sümpfen und Grasland, das eine der höchsten Konzentrationen an Wildtieren in Amerika beherbergt. Das Pantanal ist weltberühmt für seine Populationen von Jaguaren, Kaimanen, Riesenottern und dem Hyazinth-Ara, dem größten Papagei der Welt. Im Gegensatz zum dichten Amazonas-Regenwald bietet das offene Gelände des Pantanals exzellente Möglichkeiten zur Tierbeobachtung. Ein kleiner Teil des Gebiets ist als Pantanal-Nationalpark geschützt, und das gesamte Ökosystem wurde von der UNESCO zum Welterbe und Biosphärenreservat erklärt. Die Region ist auch für die traditionelle Rinderzucht auf großen Farmen (Pantaneiro-Kultur) bekannt, die sich seit Jahrhunderten an die extremen hydrologischen Zyklen angepasst hat.",
      hu: "A Pantanal a világ legnagyobb trópusi vizes élőhelye, amely 140 000 és 195 000 négyzetkilométer közötti területet foglal el, főként Brazília Mato Grosso és Mato Grosso do Sul államaiban. Ez egy hatalmas hordalékos síkság, amelynek körülbelül 80%-a víz alá kerül a novembertől márciusig tartó esős évszakban. Ezek a szezonális áradások dinamikus mozaikot hoznak létre tavakból, mocsarakból és füves pusztákból, amely Amerika egyik legnagyobb vadállat-koncentrációjának ad otthont. A Pantanal világszerte ismert jaguár-, kajmán- és óriásvidra-populációjáról, valamint a jácintkék aráról, amely a világ legnagyobb papagájfaja. Az Amazonas sűrű esőerdőjével ellentétben a Pantanal nyitott terepe kiváló lehetőségeket kínál a vadvilág megfigyelésére. A terület egy kis része a Pantanal Matogrossense Nemzeti Park néven védett, az egész ökoszisztémát pedig az UNESCO a Világörökség részévé és bioszféra-rezervátummá nyilvánította. A régió híres a hagyományos marhatenyésztésről is, ahol a helyi kultúra évszázadok óta alkalmazkodott a szélsőséges hidrológiai ciklusokhoz.",
      ro: "Pantanal este cea mai mare zonă umedă tropicală din lume, întinzându-se pe o suprafață estimată între 140.000 și 195.000 de kilometri pătrați, în principal în statele braziliene Mato Grosso și Mato Grosso do Sul. Aceasta reprezintă o câmpie sedimentară vastă, care este inundată în proporție de aproximativ 80% în timpul sezonului ploios, din noiembrie până în martie. Inundațiile sezoniere creează un mozaic dinamic de lacuri, mlaștini și pășuni, găzduind una dintre cele mai mari concentrații de viață sălbatică din America. Pantanal este renumit la nivel mondial pentru populațiile sale de jaguari, caimani, vidre uriașe și ara hiacint, cel mai mare papagal din lume. Spre deosebire de pădurea amazoniană densă, terenul deschis din Pantanal oferă condiții excelente pentru observarea animalelor în habitatul lor natural. O mică parte din teritoriu este protejată prin Parcul Național Pantanal Matogrossense, iar întregul ecosistem a fost declarat sit al Patrimoniului Mondial UNESCO și Rezervație a Biosferei. Regiunea este cunoscută și pentru cultura tradițională a crescătorilor de vite (pantaneiros), adaptați ciclurilor hidrologice extreme.",
      en: "The Pantanal is the world's largest tropical wetland, covering an area estimated between 140,000 and 195,000 square kilometers, primarily located in the Brazilian states of Mato Grosso and Mato Grosso do Sul. It is a vast alluvial plain that is roughly 80% flooded during the rainy season from November to March. These seasonal floods create a dynamic mosaic of lakes, marshes, and grasslands that support one of the highest concentrations of wildlife in the Americas. The Pantanal is world-renowned for its populations of jaguars, caimans, giant otters, and the hyacinth macaw, the world's largest parrot. Unlike the dense Amazon rainforest, the Pantanal's open landscape provides excellent visibility for wildlife spotting. A small portion of the area is protected as the Pantanal Matogrossense National Park, and the entire ecosystem has been designated a UNESCO World Heritage site and Biosphere Reserve. The region is also famous for traditional cattle ranching on large estates (fazendas), where the local culture has adapted over centuries to the extreme hydrological cycles.",
      es: "El Pantanal es un elemento notable de la geografía y cultura brasileña. Es el humedal tropical más grande del mundo y ofrece un acceso inigualable a la fauna. Es el mejor lugar de Sudamérica para ver jaguares. Se inunda cada año durante la temporada de lluvias. Este paraje natural muestra la diversidad paisajística de Brasil, desde la región amazónica hasta el Pantanal y el Cerrado. Como muchos lugares significativos en Brasil, este sitio combina peculiaridades regionales con la importancia global del quinto país más grande del mundo. Así, este lugar contribuye al perfil polifacético de Brasil, donde se entrelazan la naturaleza tropical, la herencia portuguesa, el samba, el fútbol y el carnaval.",
      pt: "O Pantanal é um elemento notável da geografia e cultura brasileiras. É a maior área úmida tropical do mundo, oferecendo acesso incomparável à vida selvagem. É o melhor lugar na América do Sul para ver onças-pintadas. É inundado todos os anos durante a estação chuvosa. Esta área natural mostra a diversidade paisagística do Brasil, da região amazônica ao Pantanal e ao Cerrado. Como muitos lugares importantes no Brasil, este local combina peculiaridades regionais com a importância abrangente do quinto maior país do mundo. Assim, este lugar contribui para o perfil versátil do Brasil, onde a natureza tropical, a herança portuguesa, o samba, o futebol e o carnaval se entrelaçam.",
      fr: "Le Pantanal est un élément remarquable de la géographie et de la culture brésiliennes. C'est la plus grande zone humide tropicale du monde, offrant un accès unique à la faune sauvage. C'est le meilleur endroit d'Amérique du Sud pour observer les jaguars. Il est inondé chaque année pendant la saison des pluies. Cet espace naturel illustre la diversité des paysages du Brésil, de la région amazonienne au Pantanal en passant par le Cerrado. Comme de nombreux sites importants au Brésil, ce lieu conjugue des particularités régionales avec l'importance globale du cinquième plus grand pays du monde. Ce site contribue ainsi au profil aux multiples facettes du Brésil, où se mêlent nature tropicale, héritage portugais, samba, football et carnaval.",
    },
