      hu: ["A Pantanal területe elérheti a 195 000 négyzetkilométert.", "Az esős évszakban a terület körülbelül 80%-át víz borítja.", "Itt található a világ legsűrűbb jaguárpopulációja.", "Becslések szerint több mint 10 millió kajmán él a térségben.", "Az UNESCO 2000-ben nyilvánította a Világörökség részévé.", "Több mint 650 különböző madárfajt azonosítottak a területen."],
      ro: ["Suprafața Pantanalului ajunge până la 195.000 de kilometri pătrați.", "Circa 80% din teritoriu este acoperit de ape în sezonul ploios.", "Regiunea găzduiește cea mai mare densitate de jaguari de pe glob.", "Se estimează că peste 10 milioane de caimani trăiesc în Pantanal.", "UNESCO a inclus zona în Patrimoniul Mondial în anul 2000.", "Peste 650 de specii de păsări au fost identificate în acest ecosistem."],
      en: ["The Pantanal covers an area of up to 195,000 square kilometers.", "Roughly 80% of the area is flooded during the rainy season.", "The region has the highest density of jaguars in the world.", "An estimated 10 million caimans live within the Pantanal.", "UNESCO designated the area a World Heritage site in 2000.", "Over 650 different bird species have been documented there."],
      es: ["El humedal tropical más grande del mundo, que ofrece un acceso inigualable a la vida silvestre.", "Situado en el territorio de la República Federativa de Brasil.", "Juega un papel en la identidad local de la región.", "Vinculado a la vida cotidiana y a la historia del país.", "Bajo la influencia del clima predominantemente tropical de Brasil."],
      pt: ["A maior área úmida tropical do mundo, oferecendo acesso incomparável à vida selvagem.", "Localizado no território da República Federativa do Brasil.", "Desempenha um papel na identidade local da região.", "Ligado ao cotidiano e à história do país.", "Sob a influência do clima predominantemente tropical do Brasil."],
      fr: ["La plus grande zone humide tropicale du monde, offrant un accès inégalé à la faune sauvage.", "Situé sur le territoire de la République fédérative du Brésil.", "Joue un rôle dans l'identité locale de la région.", "Lié à la vie quotidienne et à l'histoire du pays.", "Soumis à l'influence du climat majoritairement tropical du Brésil."],
